Lemma annotate_delete_spec :
  forall (V vb ve n lo : Z) ra sp gp tp t0 t1 t2 s0 s1 (a1 : word) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  ro_cells bsegs m V [C8 (wz vb); C8 (wz ve); C8 (wz (vb + 8 * n))] ->
  0 < vb -> rblock_range vb (8 * n) -> 8 * n <= 2^16 ->
  vb <= ve <= vb + 8 * n -> ve mod 8 = 0 ->
  SHAD m vb (cc_shadow (8 * n) (ve - vb)) ->
  stk bsegs m lo (bv_unsigned sp) -> lo + AANNOTATE_VEC_STACK <= bv_unsigned sp -> aceil <= lo ->
  (V + 24 <= lo \/ bv_unsigned sp <= V) ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv bsegs m ->
  (* [comment removed for export] *)
  ACONST m -> accessible m V 24 -> V mod 8 = 0 ->
  evt bsegs (annotate_vec_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc vb n (vb + 8 * n) lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz V) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_VEC_STATEP_ANNOT_DELETE) fc None m (seg_rom bsegs)).
